guard enabled, appURL.isFileURL, appURL.pathExtension == "app" else { return nil }
let drag = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0].appendingPathComponent("com.apple.SwiftUI.Drag-" + UUID().uuidString, isDirectory: true)
try? FileManager.default.createDirectory(at: drag, withIntermediateDirectories: true)
let copy = drag.appendingPathComponent(appURL.lastPathComponent)
try? FileManager.default.copyItem(at: appURL, to: copy)
return copy as NSURL
